SELECT COUNT(*) FROM transplant_matching tm 
INNER JOIN risk_evaluation re ON tm.match_rec_registry = re.risk_eval_registry 
WHERE tm.match_status = 'Completed';

SELECT dss_val, egs_val FROM transplant_matching tm 
INNER JOIN risk_evaluation re ON tm.match_rec_registry = re.risk_eval_registry 
WHERE tm.match_status = 'Completed' AND dss_val > 0.98 ORDER BY dss_val;
